const categoryPoints = {
  architect: 30,
  'architecture firm': 30,
  'interior designer': 30,
  builder: 28,
  'real estate developer': 28,
  contractor: 24,
  'construction company': 24,
  dealer: 15,
};

return $input.all().map(({ json: lead }) => {
  const category = String(lead.category || '').toLowerCase();
  const basePoints = Object.entries(categoryPoints)
    .find(([label]) => category.includes(label))?.[1] ?? 10;
  const verifiedPoints = lead.verification_status === 'verified' ? 20 : 0;
  const projectPoints = lead.project_name ? 10 : 0;
  const estimatedDoors = lead.estimated_doors ?? (
    Number.isInteger(lead.estimated_units) && Number.isFinite(lead.doors_per_unit)
      ? Math.round(lead.estimated_units * lead.doors_per_unit)
      : null
  );

  return {
    json: {
      ...lead,
      estimated_doors: estimatedDoors,
      score_preview: Math.min(basePoints + verifiedPoints + projectPoints, 100),
      review_required: true,
      demo_notice: 'Synthetic data only. Unverified. Do not contact or sync to a CRM.',
    },
  };
});
